// ---- Number -> Lead Source name map ----
const NUMBER_TO_SOURCE = {
  "+17869827813": "Website Main Line"
};

// ---- Buying Hero Pipeline config ----
const LOCATION_ID = "ib5jEnyqqq06FIEqlVGs";
const PIPELINE_ID = "CKQLIpRRFJImMfdZcnCK";
const NEW_LEAD_STAGE_ID = "037db392-7903-41ca-abce-c8e8ad17ce72";

const root = $input.first().json;
const body = root.body || root;
const cd = body.customData || body.custom_data || {};
// GHL nests webhook custom fields under customData; check there first, then body.
const pick = (...keys) => {
  for (const src of [cd, body]) {
    if (!src) continue;
    for (const k of keys) {
      const v = src[k];
      if (v !== undefined && v !== null && v !== "") return v;
    }
  }
  return "";
};

const dialedNumber = pick("to", "dialed_number", "number");
const callerNumber = pick("from", "phone", "caller");
const contactId    = pick("contact_id", "contactId", "id");
const firstName    = pick("first_name", "firstName");
const lastName     = pick("last_name", "lastName");

const leadSource = NUMBER_TO_SOURCE[dialedNumber] || dialedNumber || "Unknown Line";
const callerName = (firstName || lastName) ? `${firstName} ${lastName}`.trim() : (callerNumber || "New Caller");

const opportunityPayload = {
  locationId: LOCATION_ID,
  pipelineId: PIPELINE_ID,
  pipelineStageId: NEW_LEAD_STAGE_ID,
  name: `Seller Lead – ${callerName}`,
  contactId: contactId,
  status: "open",
  monetaryValue: 0,
  source: leadSource
};

return [{ json: { ok: true, matchedLeadSource: leadSource, dialedNumber, callerNumber, contactId, opportunityPayload } }];

// Count OPEN opportunities already on this contact.
const search = $input.first().json;
const opps = search.opportunities || search.data || [];
const openCount = opps.filter(o => String(o.status || '').toLowerCase() === 'open').length;

const build = $('Build Opportunity').item.json;

return [{ json: {
  openCount,
  totalOpps: opps.length,
  contactId: build.contactId,
  matchedLeadSource: build.matchedLeadSource,
  opportunityPayload: build.opportunityPayload
} }];
